/**
 * Un renglón de WS-SAVECIFRAS (OCCURS 31). Llave = banco + producto/instrumento + moneda.
 * Se acumula durante todo el paso y se vuelca a B09CIFRAS en 70003030-LLENO-CIF.
 */
public final class CifrasProducto {

    public record Llave(int banco,            // WS-CIF-BANCO 9(06)
                        int producto,         // WS-CIF-PRDNUM 9(04), parte alta de WS-CIF-PRD-INST
                        int instrumento,      // WS-CIF-INSTNUM 9(04), parte baja (REDEFINES)
                        int moneda) {}        // WS-CIF-MONEDA 9(03)

    private final Llave llave;
    // S028 local y foráneo (cargos y abonos): 9(12)V99 -> escala 2
    private BigDecimal s028CarLoc = cero(), s028AboLoc = cero(), s028CarFor = cero(), s028AboFor = cero();
    private BigDecimal saldoActual = cero();     // S9(14)V99: admite negativo
    private BigDecimal sbcSaldoL = cero(), sbcSaldoFe = cero(), sbcSaldoFr = cero();
    private int aperturas, cancelaciones;        // 9(06)
    private BigDecimal importeAperturas = cero();
    private BigDecimal aboForSpos = cero(), carForSpos = cero();
    // SBC a 6 días
    private BigDecimal sbc6EntL = cero(), sbc6EntFr = cero(), sbc6SalL = cero(), sbc6SalFr = cero();
    private BigDecimal sbc6Actual = cero();      // S9(14)V99

    private static BigDecimal cero() { return BigDecimal.ZERO.setScale(2); }
    // ... getters y métodos suma* que validan la capacidad del PIC antes de acumular
}

/** Variables WS-TEM-*: el movimiento que se está aplicando. */
public record MovimientoEnCurso(
        int producto, int instrumento, int moneda,   // 9(04), 9(04), 9(02)
        BigDecimal importe,                          // 9(12)V99 sin signo -> escala 2
        BigDecimal interesCancelacion,               // S9(10)V99 -> escala 2
        int origen,                                  // 1 = local; 2 y 3 = foráneo
        LocalDate fechaMovimiento,                   // 9(08) AAAAMMDD
        int claveMovimiento,                         // WS-TEM-CVEMOV 9(04)
        int clavePase,                               // WS-TEM-CVEPAS: clave contable hacia S151
        boolean desdeB27,                            // WS-BAN-SBC6 = 1: lo pone el lector de B27
        boolean apertura) {                          // WS-BAN-APE, viene de MOV-IND-APERTURA

    /** 88 WS88-TEM-CVEMOV-S054-DISP VALUE 3047. */
    public boolean esDisposicionS054(P105Properties p) {
        return claveMovimiento == p.claveDisposicionS054();   // p105.clave-disposicion-s054: 3047
    }

    public boolean esLocal() { return origen == 1; }
}

/** E01-PNT-S500-CRCHQRA: header y detalle del punteo para conciliar contra S054. */
public sealed interface PunteoS054Record permits PunteoS054Record.Header, PunteoS054Record.Detalle {

    record Header(int tipoReg,                    // 9(02)
                  int sistemaOrigen, int sistemaDestino,
                  LocalDate fecha, int csiOrigen,
                  LocalDate fechaProceso, LocalTime horaProceso,
                  int numeroPaso, int numeroCopia) implements PunteoS054Record {}

    record Detalle(int tipoReg,                   // 9(02), en el fuente se mueve 1
                   long autorizacionS500,         // 9(12) COMP
                   String contrato,               // 9(12) COMP -> String con ceros a la izquierda
                   int producto, int instrumento, int moneda,
                   int claveMovimiento,
                   BigDecimal importe,            // 9(10)V99: dos enteros menos que WS-TEM-IMPORTE
                   long referencia, long autorizacionS054,
                   LocalDate fechaMaquina, LocalTime horaMaquina,
                   int tipoMovimiento) implements PunteoS054Record {

        private static final BigDecimal TOPE_9_10_V99 = new BigDecimal("9999999999.99");

        public Detalle {
            if (importe.compareTo(TOPE_9_10_V99) > 0) {
                throw new ImporteFueraDeRangoException("PUNTEO/S054", importe);   // COBOL truncaba en silencio
            }
        }
    }
}

@Configuration
public class AplicacionMovimientosJobConfig {

    /** 00000000-PRINCIPAL. Cada copia (WS-COPIAP105) es una partición del mismo job. */
    @Bean
    Job aplicacionMovimientos(JobRepository repo,
                              Step cargaCatalogos,      // 50002000-CARGO-CLAVES, 50000500-CARGO-SEC
                              Step cargaCifras,         // 50001000-CARGO-CIFRAS, 50001500-LEO-SDOPEND
                              Step aplicaMovimientos,   // 50005000-APLI-MOVS
                              Step vuelcaCifras,        // 70000000-CIERRO -> 70003030-LLENO-CIF
                              ResultadoTareaListener resultado) {
        return new JobBuilder("S500P105", repo)
                .listener(resultado)
                .start(cargaCatalogos)
                .next(cargaCifras)
                .next(aplicaMovimientos)
                .next(vuelcaCifras)
                .build();
    }
}

/** SET MYSELF (TASKVALUE) TO W77-PAR-RESULT: el WFL lee este código. */
@Component
class ResultadoTareaListener implements JobExecutionListener {
    @Override
    public void afterJob(JobExecution je) {
        int codigo = je.getExecutionContext().getInt("parResult", 0);   // 78, 79, 80... por incidente
        je.setExitStatus(new ExitStatus(codigo == 0 ? "COMPLETED" : "COMPLETED_WITH_INCIDENTS",
                                        String.valueOf(codigo)));
    }
}

@Component
@StepScope
@RequiredArgsConstructor
public class AplicadorMovimientoProcessor implements ItemProcessor<MovimientoEnCurso, PolizaS151> {

    private final CatalogoClaves catalogo;          // B17 cargado en memoria
    private final AcumuladorB02 b02;
    private final TablaCifras cifras;               // WS-SAVECIFRAS
    private final ReglasCifras reglas;              // 51040000-ACT-CIFRAS
    private final ValidadorIva iva;
    private final ArchivoCancelaciones cancelaciones;

    /** 51000000-OPERO-MOV / 51000010-CONT-OPERO-MOV. */
    @Override
    public PolizaS151 process(MovimientoEnCurso mov) {
        Optional<BanderasClave> ban = catalogo.banderas(mov.claveMovimiento());   // 51010000-LEO-FUN
        if (ban.isEmpty()) {
            return null;                            // W77-SIN-B17 = 1: incidente 79, el movimiento no se aplica
        }
        boolean entradaSbc6 = mov.claveMovimiento() == 1072 && mov.desdeB27();

        b02.acumula(mov, ban.get());                // 51020000-ACUM-B02
        if (!entradaSbc6) {
            cifras.ubica(mov);                      // 51030000-LEO-TABLA
        }
        PolizaS151 poliza = reglas.aplica(mov, ban.get());   // 51040000-ACT-CIFRAS
        if (!entradaSbc6) {
            iva.valida(mov, ban.get());             // 51050000-VALIDO-IVA
        }
        cancelaciones.registraSiAplica(mov);        // 51060000-CANCEL
        return poliza;
    }
}

/** Banderas WS-BAN-* que P105 toma de cada registro de B17 (51011000-PRENDO-BAN). */
public record BanderasClave(
        int automatico,        // B17-MOV-AUTOMAT
        int origenLocal,       // B17-ORIGEN-LOCAL: > 0 trata como local aunque el origen sea 3
        int diasSbc,           // B17-DIAS-SBC
        int afectaResultados,  // B17-AFECTA-RESLT
        boolean cargo,         // B17-TIPO-MOV = 1
        boolean abono,         // B17-TIPO-MOV = 2
        int afectaS052, int afectaS028, int afectaS408) {

    /** Las banderas se reinician en cada movimiento: un record nuevo por clave evita arrastrar valores. */
    public static BanderasClave de(ClaveB17 b17) {          // @Entity del dataset B17
        return new BanderasClave(b17.getMovAutomat(), b17.getOrigenLocal(), b17.getDiasSbc(),
                Math.max(b17.getAfectaReslt(), 0),
                b17.getTipoMov() == 1, b17.getTipoMov() == 2,
                b17.getAfectaS052(), b17.getAfectaS028(), b17.getAfectaS408());
    }

    /** Origen efectivo para contabilizar: local si el origen es 1 o si B17 lo fuerza. */
    public boolean tratarComoLocal(MovimientoEnCurso m) {
        return m.esLocal() || origenLocal > 0;
    }
}

@Service
@RequiredArgsConstructor
public class ReglasCifras {

    private final P105Properties props;          // claves de cancelación y de SBC a 6 días
    private final MovSbcRepository b27;          // S500 B27MOVSBC (JPA)

    /** 51040000-ACT-CIFRAS, primer bloque. */
    void aplicaSbcYConteos(MovimientoEnCurso m, CifrasProducto c, boolean movB07) {
        BigDecimal imp = m.importe();

        if (m.claveMovimiento() == props.sbc6Entrada() && movB07) {          // 1072
            b27.save(MovSbc.salidaProgramada(m, props.sbc6Salida()));      // 51041000-CREOB27, clave 3036
            c.sumaSbc6Actual(imp);
            if (m.esLocal()) c.sumaSbc6EntL(imp); else c.sumaSbc6EntFr(imp);
        }
        if (m.claveMovimiento() == props.sbc6Entrada() && m.desdeB27()) {
            sbcB07(m);                                                     // 51042000-SBC-B07
        }
        if (m.claveMovimiento() == props.sbc6Salida()) {                   // 3036
            if (m.esLocal()) c.sumaSbc6SalL(imp); else c.sumaSbc6SalFr(imp);
            c.restaSbc6Actual(imp);
        }
        if (m.apertura()) {
            c.sumaApertura(imp);                                           // +1 y +importe
        }
        if (props.clavesCancelacion().contains(m.claveMovimiento())) {     // 2014 2093 2216 2269 2271 2365 2534
            c.sumaCancelacion();
        }
    }
}

