/** 51040000-ACT-CIFRAS: decide si el movimiento afecta S028 (51044000-VAL028). */
void aplicaS028SiProcede(MovimientoEnCurso m, BanderasClave ban, boolean dialogo, CifrasProducto c) {
    if (m.esLocal() || dialogo || ban.origenLocal() > 0) {
        boolean entradaSbc6DeB27 = m.claveMovimiento() == props.sbc6Entrada() && m.desdeB27();
        if (!entradaSbc6DeB27) {                     // 1072 con WS-BAN-SBC6 = 1: NEXT SENTENCE
            validaS028(m, ban, dialogo, c);
        }
    }
}

/** 51045000-VAL052: cargos y abonos al S052 con la misma excepción de origen. */
void validaS052(MovimientoEnCurso m, BanderasClave ban, CifrasProducto c) {
    boolean local = m.esLocal() || ban.automatico() > 0 || ban.origenLocal() > 0;
    switch (ban.afectaS052()) {
        case 0 -> { }
        case 1 -> { if (local) car052(m, c); else c.cargoForaneoPosicion(m.importe()); }  // resta de SDO-ACTUAL
        case 2 -> { if (local) abo052(m, c); else c.abonoForaneoPosicion(m.importe()); }  // suma a SDO-ACTUAL
        default -> incidentes.registra(80, "ERR PARAM AFECTA-S052 EN B17", m);       // no aborta
    }
}

@Component
@RequiredArgsConstructor
public class PolizaS151Mapper {

    private final P105Properties props;

    /** 51043000-CALL-151: arma el área WS-S151-0101-*-I que recibe la librería. */
    public PolizaS151 desde(MovimientoEnCurso m, Contexto ctx, boolean dialogo, long autorizacion) {
        return PolizaS151.builder()
                .funcion(1)                                            // alta de movimiento
                .fechaContable(ctx.fechaPaso()).fechaValor(ctx.fechaPaso())
                .fechaUltimoMovimiento(ctx.fechaMovimiento())
                .importe(m.importe())                                  // BigDecimal escala 2
                .claveTransaccion(m.clavePase())
                .fechaMovimiento(ctx.fechaDia())
                .horaMovimiento(props.horaMovimientoS151())            // 093000 fijo en el fuente
                .sucursalPromotora(ctx.sucursalPromotora())
                .autorizacion(autorizacion)                            // WS-CONAUT: consecutivo del paso
                .tipoProceso(props.tipoProcesoPorCopia().get(ctx.copia())) // copia 1 -> 15, 2 -> 16, otra -> 17
                .origen(dialogo ? 2 : m.origen())                      // los de diálogo viajan como origen 2
                .bancoOrigen(ctx.hostDah() ? m.bancoOrigen() : props.bancoDefault())   // 007
                .bancoDestino(ctx.hostDah() ? m.bancoDestino() : props.bancoDefault())
                .build();
    }
}

